import re

US_STATES = {
    'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA',
    'KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ',
    'NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT',
    'VA','WA','WV','WI','WY','DC'
}

def wifi_offered(attrs):
    if not attrs or not isinstance(attrs, dict):
        return False
    val = attrs.get('WiFi') or attrs.get('wifi')
    if val is None:
        return False
    v = str(val).strip()
    # strip leading u and quotes
    if v.startswith('u') and len(v) > 1 and v[1] in ("'", '"'):
        v = v[1:]
    v = v.strip("'\"").lower()
    return v not in ('no', 'none', '')

def parse_state(desc):
    if not desc:
        return None
    # Try ZIP-anchored pattern
    m = re.search(r'\b([A-Z]{2})\b\s*\d{5}', desc)
    if m and m.group(1) in US_STATES:
        return m.group(1)
    # Fallback to ', ST'
    m = re.search(r',\s*([A-Z]{2})\b', desc)
    if m and m.group(1) in US_STATES:
        return m.group(1)
    return None

